import Foundation

/// Stores sealed packages only. Keys are generated by the inventory, never supplied by a remote user.
public protocol ObjectStore: Sendable {
    func put(_ key: String, data: Data) async throws
    func get(_ key: String) async throws -> Data
    func delete(_ key: String) async throws
    func head(_ key: String) async throws -> Int?
}

public struct StorageError: Error, Equatable, Sendable {
    public let code: String
    public init(_ code: String) { self.code = code }
}

public enum ObjectStoreLimits {
    public static let maxBytes = 64 * 1024 * 1024
    public static func validateKey(_ key: String) throws {
        guard !key.isEmpty, key.utf8.count <= 1024, !key.hasPrefix("/"), !key.hasSuffix("/"),
              !key.contains("\\"), !key.unicodeScalars.contains(where: { $0.value < 32 || $0.value == 127 }),
              key.split(separator: "/", omittingEmptySubsequences: false).allSatisfy({ !$0.isEmpty && $0 != "." && $0 != ".." }) else { throw StorageError("invalid_object_key") }
    }
}
